package com.campus.lostfound;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.time.LocalDate; import java.time.temporal.ChronoUnit; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api") @CrossOrigin(originPatterns="*") public class ApiController {
 private final UserRepository users; private final ItemRepository items; private final ClaimRepository claims; private final BCryptPasswordEncoder enc=new BCryptPasswordEncoder();
 public ApiController(UserRepository u,ItemRepository i,ClaimRepository c){users=u;items=i;claims=c;}
 public record Auth(String name,String email,String password){} public record ItemInput(String type,String itemName,String category,String description,String location,LocalDate itemDate,String imageUrl,Long userId){} public record ClaimInput(Long userId,String message){} public record StatusInput(String status){}
 Map<String,Object> userView(AppUser u){return Map.of("id",u.id,"name",u.name,"email",u.email);} AppUser user(Long id){return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));} ItemReport item(Long id){return items.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Item not found"));} String s(String v){return v==null?"":v;}
 @PostMapping("/auth/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@RequestBody Auth a){if(a.name()==null||a.name().isBlank()||a.email()==null||!a.email().contains("@")||a.password()==null||a.password().length()<6)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter name, valid email, and password of at least 6 characters");if(users.existsByEmailIgnoreCase(a.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");return userView(users.save(new AppUser(a.name().trim(),a.email().trim().toLowerCase(),enc.encode(a.password()))));}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Auth a){AppUser u=users.findByEmailIgnoreCase(s(a.email()).trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(a.password()==null||!enc.matches(a.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return userView(u);}
 Map<String,Object> view(ItemReport i){Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.id);m.put("type",i.type);m.put("itemName",i.itemName);m.put("category",i.category);m.put("description",i.description);m.put("location",i.location);m.put("itemDate",i.itemDate);m.put("imageUrl",i.imageUrl);m.put("status",i.status);m.put("owner",userView(i.owner));return m;}
 @GetMapping("/items") public List<Map<String,Object>> list(@RequestParam(required=false)String q,@RequestParam(required=false)String type,@RequestParam(required=false)String category){return items.findAllByOrderByIdDesc().stream().filter(i->type==null||type.isBlank()||i.type.equalsIgnoreCase(type)).filter(i->category==null||category.isBlank()||i.category.equalsIgnoreCase(category)).filter(i->q==null||q.isBlank()||(s(i.itemName)+" "+s(i.description)+" "+s(i.location)+" "+s(i.category)).toLowerCase().contains(q.toLowerCase())).map(this::view).toList();}
 @PostMapping("/items") public Map<String,Object> create(@RequestBody ItemInput a){if(a.userId()==null||a.itemName()==null||a.itemName().isBlank()||a.category()==null||a.type()==null||!List.of("LOST","FOUND").contains(a.type().toUpperCase()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Type, item name, category and user are required");ItemReport i=new ItemReport();i.type=a.type().toUpperCase();i.itemName=a.itemName().trim();i.category=a.category();i.description=a.description();i.location=a.location();i.itemDate=a.itemDate();i.imageUrl=a.imageUrl();i.owner=user(a.userId());return view(items.save(i));}
 @GetMapping("/items/{id}/matches") public List<Map<String,Object>> matches(@PathVariable Long id){ItemReport target=item(id);return items.findAllByOrderByIdDesc().stream().filter(i->!i.id.equals(id)&&!i.type.equals(target.type)&&i.status.equals("OPEN")).map(i->Map.entry(i,score(target,i))).filter(e->e.getValue()>0).sorted((a,b)->b.getValue()-a.getValue()).limit(8).map(e->{Map<String,Object> m=view(e.getKey());m.put("matchScore",e.getValue());return m;}).toList();}
 int score(ItemReport a,ItemReport b){int n=0;if(s(a.category).equalsIgnoreCase(s(b.category)))n+=3;Set<String>w=Arrays.stream((s(a.itemName)+" "+s(a.description)).toLowerCase().split("[^a-z0-9]+")).filter(x->x.length()>2).collect(Collectors.toSet());if(Arrays.stream((s(b.itemName)+" "+s(b.description)).toLowerCase().split("[^a-z0-9]+")).anyMatch(w::contains))n+=2;if(a.location!=null&&a.location.equalsIgnoreCase(b.location))n+=2;if(a.itemDate!=null&&b.itemDate!=null&&Math.abs(ChronoUnit.DAYS.between(a.itemDate,b.itemDate))<=7)n++;return n;}
 Map<String,Object> claimView(ItemClaim c){return Map.of("id",c.id,"itemId",c.item.id,"itemName",c.item.itemName,"claimant",userView(c.claimant),"message",s(c.message),"status",c.status,"createdAt",c.createdAt.toString());}
 @PostMapping("/items/{id}/claims") public Map<String,Object> claim(@PathVariable Long id,@RequestBody ClaimInput a){ItemReport i=item(id);if(a.userId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Log in first");AppUser u=user(a.userId());if(i.owner.id.equals(u.id))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"You cannot claim your own report");if(!i.type.equals("FOUND"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Claims are for found items");ItemClaim c=new ItemClaim();c.item=i;c.claimant=u;c.message=a.message();return claimView(claims.save(c));}
 @GetMapping("/claims") public List<Map<String,Object>> getClaims(@RequestParam(required=false)Long userId){return (userId==null?claims.findAllByOrderByCreatedAtDesc():claims.findByClaimantIdOrderByCreatedAtDesc(userId)).stream().map(this::claimView).toList();}
 @PatchMapping("/claims/{id}") public Map<String,Object> review(@PathVariable Long id,@RequestBody StatusInput a){ItemClaim c=claims.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Claim not found"));String st=s(a.status()).toUpperCase();if(!List.of("PENDING","APPROVED","REJECTED").contains(st))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");c.status=st;if(st.equals("APPROVED")){c.item.status="RECOVERED";items.save(c.item);}return claimView(claims.save(c));}
 @PatchMapping("/items/{id}/status") public Map<String,Object> status(@PathVariable Long id,@RequestBody StatusInput a){ItemReport i=item(id);String st=s(a.status()).toUpperCase();if(!List.of("OPEN","RECOVERED").contains(st))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid item status");i.status=st;return view(items.save(i));}
}
